window.Q_TRANSLATIONS = {"q1": {"text": "What is the main factor influencing the design of a B2C e-commerce solution?", "options": ["Its multi-tenant SaaS nature and its fees", "Direct access to the database", "The ability to install any server package", "The absence of caching mechanisms"], "explanation": "SFCC is a multi-tenant SaaS platform. It does not provide direct access to the database and protects resources through quotas."}, "q2": {"text": "What does a code version represent?", "options": ["A copy of all the data on the site", "An expanded version of cartridges", "A search index", "A group of Business Manager users"], "explanation": "The code version groups deployed code. Only one is active per instance, and activating it does not replicate data."}, "q3": {"text": "Where should the adaptation of Script API objects for a view be located?", "options": ["In the Controller only", "At the ISML", "In a Model or ViewModel", "In a site preference"], "explanation": "The models map platform objects to secure, presentation-specific contracts."}, "q4": {"text": "What is a typical response from an architect when faced with a decision?", "options": ["Always choose the latest technology", "Specifying a memory quota in data migration scenarios", "Avoid alternatives to be conclusive", "Outline requirements, trade-offs, operation, and rollback"], "explanation": "A well-considered decision takes into account requirements, constraints, risks, observability, rollout, and recovery."}, "q5": {"text": "Which scope best describes an \"instance\"?", "options": ["A specific environment with its own life cycle", "A comprehensive product lineup", "A collection of sites for analytical use cases", "A catalog type verified in the staging environment"], "explanation": "An instance is an isolated environment (development, staging, production) within a realm."}, "q6": {"text": "Why does multi-tenancy affect every architectural decision?", "options": ["Because it limits the team's creativity in the context of the international storefront", "Because any error is replicated to other tenants, and resources are finite", "Because it eliminates versioning with authorization from the platform team", "Because it prevents the use of JavaScript within the SLA agreed upon with the merchant"], "explanation": "Designing within quotas and with isolation protects all tenants and your own SLA."}, "q7": {"text": "What does it mean for code and data to follow different cycles?", "options": ["They should be scaled together using a distributed cache for analytical use cases", "They cannot be deployed simultaneously via external webhooks validated against the API contract", "A release must synchronize the versions of the code, metadata, preferences, indexes, and replication.", "Only Sandbox synchronizes, as verified in the staging environment using a distributed cache"], "explanation": "The release should treat each layer as a dependency that can be broken in a different order."}, "q8": {"text": "How is the cartridge path resolved?", "options": ["From right to left", "Alphabetically", "Based on the deployment date", "From left to right"], "explanation": "The first matching resource from left to right takes precedence."}, "q9": {"text": "Why shouldn't you modify `app_storefront_base`?", "options": ["Because it makes upgrades difficult and hides the custom delta", "Because it prevents the use of ISML that has been validated against the API contract", "Because it is read-only for analytical use cases", "Because it does not allow JavaScript for analytical use cases"], "explanation": "Extensions must reside in custom cartridges located on the left to ensure they can be updated."}, "q10": {"text": "What does `module.superModule` provide?", "options": ["The browser module for analytics use cases", "The following implementation applies to the cartridge path", "A remote service with the site's regional settings", "The shopper's session, supported by the operations team"], "explanation": "It allows you to extend a base implementation while preserving its contract."}, "q11": {"text": "What mechanism decouples payment, fraud, or tax extensions?", "options": ["Content slots", "Price Lists", "Hooks", "Remote includes"], "explanation": "Hooks define extension points that are registered and invoked by HookMgr."}, "q12": {"text": "In hooks.json, what does the \"hooks\" array represent?", "options": ["A list of routes for advanced reporting purposes", "DOM events following the pattern defined in SFRA", "A collection of preferences for analytical use cases", "Available Functions and Their Execution Sequence"], "explanation": "The array specifies the hook name, script, order, and whether to abort the string."}, "q13": {"text": "How are integration cartridges (int_*) and plugin cartridges (plugin_*) organized?", "options": ["int_* is linked to a specific provider; plugin_* provides generic functionality governed by Salesforce", "They are synonymous with the platform team's authorization during controller initialization", "plugin_* is private within the SLA agreed upon with the verified merchant in the staging environment", "int_* contains only ISML in data migration scenarios for advanced reporting purposes"], "explanation": "Distinguishing between them correctly facilitates upgrades and reduces contractual risks."}, "q14": {"text": "Why should you avoid a monolithic cartridge?", "options": ["For aesthetic reasons, using external webhooks for analytical use cases", "Because it increases the attack surface and blocks deployments", "Because it takes up a lot of verified space in the staging environment", "For linting rules used for advanced reporting"], "explanation": "Cartridges organized by domain (checkout, search, loyalty) reduce the blast radius of each release."}, "q15": {"text": "What should a POST endpoint that modifies a profile protect?", "options": ["HTTPS only, validated against the API contract", "Solo authentication for analytical use cases", "HTTPS, CSRF, Authorization, and Validation", "Output encoding only"], "explanation": "These controls complement each other: proper methodology, HTTPS, CSRF, authentication, authorization, and server-side validation."}, "q16": {"text": "What is the preferred file extension for adding data to an existing route?", "options": ["Always validate the replacement against the API contract", "Change app_storefront_base", "Copy the base controller", "append or prepend if they keep the contract"], "explanation": "Append and prepend minimize the delta and typically preserve future improvements to the base controller."}, "q17": {"text": "What does `return next()` mean in a middleware function?", "options": ["It continues the string and explicitly marks the end of the middleware", "Always send a JSON file with the standard dashboard monitoring data", "Roll back a transaction using the insights provided by the log", "Enable the cache with automatic retries configured"], "explanation": "next continues the string; returning it explicitly marks the end of the local flow."}, "q18": {"text": "What is an anti-pattern in a controller?", "options": ["Lightweight orchestration for analytical use cases", "External call without a timeout during checkout", "Explicit JSON Contract", "Query String Validation"], "explanation": "A remote service without a timeout can block a critical path and cause the provider to go down."}, "q19": {"text": "When should you use `prepend` instead of `append`?", "options": ["Always prepend within the standard checkout flow during the page rendering phase", "Only in production during synchronization with the OMS using the site's regional configuration", "Use \"append\" when you need data after rendering; use \"prepend\" when you need to authorize first", "Only at checkout, according to the current deployment model coordinated with the operations team"], "explanation": "Order matters for authorization, validation, and view data composition."}, "q20": {"text": "What should a `server.forms.getForm` contain?", "options": ["Browser data via external webhooks", "A cookie that follows the pattern defined in SFRA", "Arbitrary JSON for analytical use cases", "An XML definition and the request form"], "explanation": "The XML definition is validated and bound to the request, preventing insecure manual binding."}, "q21": {"text": "What is res.on(\"route:BeforeComplete\") used for?", "options": ["For final logic before completing the response", "To start caching according to the pattern defined in SFRA", "To upload a verified file to the staging environment", "To abort the transaction for analytical use cases"], "explanation": "The event is triggered when all the middleware processes have finished, allowing for final adjustments without altering the order."}, "q22": {"text": "What is the risk of intercepting a response that contains a CSRF token?", "options": ["Do not cache via external webhooks", "The token should be reused among shoppers", "This should be ruled out for analytical use cases", "Breaking HTTPS via external webhooks"], "explanation": "A cached CSRF token bypasses CSRF protection and creates a serious vulnerability."}, "q23": {"text": "What should be avoided in ISML?", "options": ["Resources that can be translated via external webhooks", "Output encoding using SOAP web services", "Heavy-duty business logic and Script API calls", "Includes locales for advanced reporting purposes"], "explanation": "ISML should focus on presentation; data preparation is the responsibility of the controller, model, or helper."}, "q24": {"text": "How much does a remote include cost?", "options": ["None with automatic retries configured", "It only increases the size of the CSS for analytical use cases", "Disable JavaScript by using a distributed cache", "It adds an internal execution step, even though it isolates the cache"], "explanation": "You can extract a dynamic section from a cached page, but it adds extra work and latency."}, "q25": {"text": "When extending a base model, what should be preserved?", "options": ["The Expected Signing and Contract", "The color of the front end", "The name of the site", "The entire session"], "explanation": "An extended model must remain compatible with its users and with the base implementation."}, "q26": {"text": "Why shouldn't a complete Script API object be exposed to the view?", "options": ["It has no properties according to the current deployment model", "You can filter data and integrate the presentation with the platform", "Prevents the use of CSS with the observability provided by the log", "It's always empty when automatic retries are configured"], "explanation": "A view model limits data, reduces coupling, and prevents accidental exposure."}, "q27": {"text": "How is view data propagated between middleware components?", "options": ["Global Variables for Analytical Use Cases", "session.custom for analytical use cases", "res.getViewData() / res.setViewData()", "dw.system.Site for analytical use cases"], "explanation": "It is the contract shared by the middleware chain; global changes break isolation."}, "q28": {"text": "What workflow do versioned assets follow?", "options": ["Host in an external bucket during the page rendering phase", "Always upload using the same name", "Manually change them for analytical use cases", "Hash in URL or name for automatic invalidation"], "explanation": "Proper cache-busting in CI prevents infinite 304 responses and deployments with outdated files."}, "q29": {"text": "What is the risk of a nested <isinclude url>?", "options": ["Each level adds an internal execution and can invalidate the cache", "It works exactly the same way through the nightly cataloging service", "It only affects CSS when following the vendor's upgrade guide", "Only images coordinated with the operations team matter"], "explanation": "Nesting remote includes introduces latency and increases the number of failure points."}, "q30": {"text": "What is the main defining feature of a storefront catalog?", "options": ["The code version", "Navigating the site", "WHO Credentials", "The Roles of a Business Manager"], "explanation": "The storefront catalog organizes categories and shopping navigation; the master database consolidates reusable product data."}, "q31": {"text": "Which of these products is not usually available for direct purchase?", "options": ["Variant", "Standard", "Master's Degree", "Bundle"], "explanation": "The master item groups variants and defines variation attributes, but the purchasable SKU is usually the variant."}, "q32": {"text": "Is it correct to say that the lowest price always wins?", "options": ["Yes, with no exceptions via external webhooks", "Only for bundles during controller initialization", "Verified only in the staging environment for analytical use cases", "No; allocation, currency, validity, context, and hierarchy all play a role"], "explanation": "Pricing decisions depend on several factors; \"lowest price wins\" is a dangerous oversimplification."}, "q33": {"text": "What might a new refinable attribute for a product require?", "options": ["Update the search index", "Just restart the browser", "Create an order", "Change the SLAS client"], "explanation": "The attributes used for searching, sorting, or refining require consistent configuration and indexing."}, "q34": {"text": "What is the difference between the master catalog and the storefront catalog?", "options": ["The token is validated against the API contract based on the current deployment model", "The master contains canonical data; the storefront defines the e-commerce navigation", "The language of the product through the use of distributed caching for analytical use cases", "The site's language via external webhooks with automatic retries configured"], "explanation": "A single master can be reused across multiple storefronts with different navigation."}, "q35": {"text": "What role does an inventory list play?", "options": ["Replaces \"product\" during the page rendering phase", "Save coupons during synchronization with the OMS", "Assign availability to sites and locations", "This is a search index for analytical use cases"], "explanation": "Without an inventory list, there is no consistent availability in the storefront."}, "q36": {"text": "When is it appropriate to mark an attribute as refinable?", "options": ["When used in admin", "When used in JavaScript for analytical use cases", "When shown on the invoice", "When used in faceted navigation"], "explanation": "Only attributes that can actually be filtered justify the cost of indexing."}, "q37": {"text": "Who should calculate the final totals for basketball?", "options": ["The server", "The browser", "The analytics provider", "The CDN"], "explanation": "The client is not a reliable source for prices, discounts, taxes, or totals."}, "q38": {"text": "A payment provider returns a timeout. What should you do first?", "options": ["Charge again during the page rendering phase", "Check the status using the idempotent reference", "Cancel all orders for analytical use cases", "Ignore the payment arranged with the operations team"], "explanation": "A timeout results in an ambiguous outcome. Retrying blindly may double the charge."}, "q39": {"text": "Which operation should not be included within `Transaction.wrap`?", "options": ["A Brief Persistent Script", "Update an amount", "A remote HTTP call", "Change a custom attribute"], "explanation": "Network calls prolong deadlocks and combine external uncertainty with local atomicity."}, "q40": {"text": "What narrows the scope of PCI?", "options": ["Save PAN to session.custom", "Send card data to the OMS", "Enter the encrypted CVV", "Hosted fields or provider tokenization"], "explanation": "Tokenizing and using components hosted by the provider reduces the need to handle sensitive data directly."}, "q41": {"text": "What does idempotence mean in a payment transaction?", "options": ["Repeating the same operation does not produce duplicate results", "The user can cancel using SOAP web services", "Verify that the charge takes effect immediately in the staging environment", "That the bank accepts the transaction for advanced reporting purposes"], "explanation": "An idempotent key allows for safe retries in the event of timeouts."}, "q42": {"text": "What is the difference between authorization and capture?", "options": ["These are synonymous with configured automatic retries", "Authorization reserves funds; capture executes the final charge", "\"Solo captura\" exists only in the context of the international storefront", "Solo Authorization processes the charge through external webhooks"], "explanation": "Separating these two steps allows for workflows such as pre-authorization, capture upon shipment, and subsequent refund."}, "q43": {"text": "An anti-fraud check returns \"DECLINE.\" What should I do?", "options": ["Force payment to be validated against the API contract for analytical use cases", "Always cancel in preview and staging mode", "Submit for manual review in accordance with policy and keep the shopper informed", "Retry the payment using external webhooks during the page rendering phase"], "explanation": "Business policies and rules set the course, not an automated response."}, "q44": {"text": "When is a custom attribute most appropriate?", "options": ["For any secret based on the current deployment model", "To store millions of analytics events", "To replace an OMS with the observability provided by logs", "When the data pertains to the lifecycle of a System Object"], "explanation": "If the data is a natural part of Product, Order, or CustomerProfile, a custom attribute is usually consistent."}, "q45": {"text": "What is a good property of a transaction?", "options": ["Concise, deterministic, and limited to related documents", "Long and involves remote calls during synchronization with the OMS", "Shared among requests with a focus on code maintainability", "No rollback capability validated against the API contract"], "explanation": "Short transactions minimize deadlocks and simplify recovery."}, "q46": {"text": "What should you do with a results iterator?", "options": ["Always convert it into a giant array", "Close the iterator when appropriate", "Save it in the session", "Share it with the front end"], "explanation": "Processing it in a limited manner and closing it prevents unnecessary use of resources."}, "q47": {"text": "What should I use for complex analytics on millions of orders?", "options": ["Complete scans from the storefront", "ISML through the nighttime cataloging service", "An external system powered by exports", "session.custom in coordination with the operations team"], "explanation": "SFCC is not an analytical database; high-volume queries should be offloaded to an appropriate platform."}, "q48": {"text": "When is a replicable custom object preferable?", "options": ["For ephemeral logs using the current commit pipeline", "For PII data based on the site's regional settings", "For tokens supported by the operations team", "For configurations that are deployed across environments"], "explanation": "Replicable/stageable resources reside in metadata and are moved along with the deployment."}, "q49": {"text": "Why explicitly close an iterator?", "options": ["To free up resources and prevent leaks", "It is not necessary for analytical use cases", "To improve your search", "To clear the cache"], "explanation": "The system's iterators manage resources that should be released."}, "q50": {"text": "What impact does a full scan have on production?", "options": ["None via external webhooks", "It consumes quotas and increases overall latency", "This only affects the admin for analytical use cases", "This only affects mobile users"], "explanation": "A full scan can exhaust the Script API and cause checkout SLOs to fail."}, "q51": {"text": "What should every external service include?", "options": ["Credentials in the code with automatic retries configured", "An infinite timeout caused by using SOAP web services", "Timeouts, metrics, log filtering, and error handling", "Retry for any error using scheduled jobs"], "explanation": "The Service Framework must combine secure configuration, observability, and resilience."}, "q52": {"text": "When is it safe to try again?", "options": ["Whenever a timeout is validated against the API contract", "Only from ISML in preview and staging mode", "In any payment made using distributed cache", "When the operation is idempotent and the failure is transient"], "explanation": "Retry requires classifying the error and ensuring that retrying does not duplicate effects."}, "q53": {"text": "What does a circuit breaker do?", "options": ["Temporarily stop sending requests to a degraded provider", "Calculate the response using the standard dashboard monitoring", "Recreate the basketball game using the observability provided by the log", "Replicate the catalog with automatic retries configured"], "explanation": "The circuit breaker limits cascading failures and enables recovery of external service."}, "q54": {"text": "Where should service credentials be configured?", "options": ["In a comment in the code", "In Service Credentials/Secure Configuration", "In a content asset for analytical use cases", "In the query string validated against the API contract"], "explanation": "Secrets should not be stored in code, logs, or accessible flat configuration files."}, "q55": {"text": "What does dw.svc guarantee to external service providers?", "options": ["Database Connection Within the Standard Checkout Workflow for Analytical Use Cases", "Direct access to the platform during synchronization with the OMS", "Unified configuration of timeouts, credentials, callbacks, and logging", "DNS Resolution Based on the Current Deployment Model for Analytical Use Cases"], "explanation": "dw.svc centralizes external integration and separates it from flow control."}, "q56": {"text": "What is the bulkhead pattern?", "options": ["Strengthen the firewall during the page rendering phase", "DNS Balancing Using the Nighttime Cataloging Service", "Cache distributed according to the vendor's upgrade guide", "Isolate resources so that an integration does not deplete the shared resources"], "explanation": "Isolating connections and threads prevents one provider from affecting the performance of others."}, "q57": {"text": "What is a logical outbox used for?", "options": ["To distinguish asynchronous side effects from the response", "To save the invoice with the site's regional settings", "To rewrite the response with support from the operations team", "To log in during the standard checkout process"], "explanation": "The outbox decouples the main request from tasks that might fail without disrupting the purchase."}, "q58": {"text": "What is the best approach for millions of records?", "options": ["Load everything into memory", "Chunk processing", "A GET route", "A remote include"], "explanation": "Processing in chunks reduces memory usage and transaction overhead."}, "q59": {"text": "Which property makes it easy to retry a job after a failure?", "options": ["An infinite timeout", "Personalization Based on Cookies", "Idempotence", "Lack of metrics"], "explanation": "An idempotent job can be re-run without duplicating effects or corrupting the final state."}, "q60": {"text": "What should a job log?", "options": ["Complete tokens with automatic retries configured", "Just a welcome message via the presentation layer", "Card Information in the Context of the International Storefront", "Read, processed, discarded, errors, and duration"], "explanation": "Operational metrics make it possible to detect lag, invalid records, and performance degradation."}, "q61": {"text": "What prevents dangerous overlaps?", "options": ["Control Concurrency on Shared Resources", "Allow all parallel jobs", "Increase the payload size for analytical use cases", "Disable rollback via external webhooks"], "explanation": "Two jobs writing to the same resources can cause locks, duplicates, and inconsistencies."}, "q62": {"text": "Which method is exposed by a chunk step?", "options": ["stepType based on the current deployment model, as coordinated with the operations team", "read, process, write (and also beforeStep/afterStep/getTotalCount as needed)", "start, stop, status, along with the observability provided by the log for analytical use cases", "processRecord with automatic retries configured, validated against the API contract"], "explanation": "The framework manages the entire chunk lifecycle and allows you to customize each phase."}, "q63": {"text": "Why move a large export to a job?", "options": ["Because it looks nicer when coordinated with the operations team", "According to traditions during the consolidation phase of the cart", "To avoid blocking the storefront request and to apply batch quotas", "SEO validated against the API contract during the page rendering phase"], "explanation": "That's the correct distinction: synchronous storefront, asynchronous batch."}, "q64": {"text": "What does \"quarantine\" do in a feed?", "options": ["Delete the file within the standard checkout workflow", "Encrypt the file during synchronization with the OMS", "Translate the file with a focus on code maintainability", "Isolates invalid records without aborting the entire batch"], "explanation": "Quarantine prevents the loss of an entire feed due to a few corrupted records."}, "q65": {"text": "Should I enable a code version of Replica Data?", "options": ["No", "Yes, always", "Solo catalogs", "Solo price books"], "explanation": "Code and data have different deployment cycles and must be coordinated."}, "q66": {"text": "What should an SFCC release include?", "options": ["JavaScript only via the current commit pipeline for analytics use cases", "Compatibility between code, metadata, preferences, services, and indexes", "CSS only, with support from the operations team for analytical use cases", "Production only within the standard checkout flow"], "explanation": "A version may depend on definitions, configurations, and data that must be deployed in a specific order."}, "q67": {"text": "What is a typical code rollback?", "options": ["Delete the realm", "Delete orders for analytical use cases", "Restore the previous code version", "Change the master catalog"], "explanation": "The previous version can be reactivated if it remains compatible with the data changes that have been made."}, "q68": {"text": "What policy applies to Business Manager users?", "options": ["Full access following the pattern defined in SFRA", "No audit within the SLA agreed upon with the merchant", "Shared credentials for analytical use cases", "Least privilege and separation of duties"], "explanation": "RBAC must restrict both visible modules and critical functional actions."}, "q69": {"text": "What is the order of the steps in a mature pipeline?", "options": ["Build, test, package, deploy to non-production, smoke test, coordinated activation", "Test, build, smoke, and production within the SLA agreed upon with the merchant", "I only use Smoke for data migration scenarios via external webhooks", "Direct production using the cartridge's default settings"], "explanation": "This approach reduces risk and allows for the detection of errors before they affect production."}, "q70": {"text": "What are the risks of replicating an incomplete configuration?", "options": ["None validated against the API contract", "The destination site fails because it cannot find any definitions", "This only affects reports that use a distributed cache", "Only to the back office via external webhooks"], "explanation": "A replication dry run or preliminary validation prevents a target from receiving a subset that could break integrations or the storefront."}, "q71": {"text": "What is the difference between staging and production?", "options": ["Just the logo, based on the current deployment model", "Only the domain with standard dashboard monitoring", "Synthetic data vs. real traffic; staging is the source of replication", "Performance with automatic retries enabled only"], "explanation": "Treating the staging environment as a production environment is key to avoiding surprises."}, "q72": {"text": "When does Page Designer stand out?", "options": ["Secret rotation for analytical use cases", "Payment Authorization for Analytical Use Cases", "In order queries for analytical use cases", "In the visual layout of pages and regions"], "explanation": "Page Designer provides editorial autonomy through managed components and regions."}, "q73": {"text": "What are the risks associated with unvalidated merchant content?", "options": ["XSS", "Inventory Deadlock", "Duplicate of code version", "Currency Exchange"], "explanation": "Editable content is also user input and must be validated and escaped as appropriate."}, "q74": {"text": "What controls the explosion of URLs by facets?", "options": ["Save filters in orders for analytical use cases", "A Strategy for Indexing, Canonical Tags, and Robots", "Disable HTTPS by following the vendor's upgrade guide", "Using `session.custom` within the standard checkout flow"], "explanation": "Technical SEO must determine which combinations are crawlable, indexable, and canonical."}, "q75": {"text": "What sets a content slot apart from Page Designer?", "options": ["Page Designer only stores prices through the current commit pipeline", "There is no difference in the site's regional configuration through the presentation layer.", "A slot is a known, programmable location; Page Designer creates the visual structure", "The slot authenticates shoppers within the standard checkout flow for analytical use cases"], "explanation": "These are complementary tools with varying degrees of editorial freedom and targeting capabilities."}, "q76": {"text": "What is hreflang, and when should you use it?", "options": ["An HTTP attribute with the cartridge's default configuration", "A language cookie via the presentation layer for analytics use cases", "A cache header validated against the external API contract", "A note to specify the language/region of the alternate page in a multisite installation"], "explanation": "It allows search engines to serve the correct localized version based on the user."}, "q77": {"text": "When is a dynamic sitemap recommended?", "options": ["When the catalog or content changes frequently and you want quick discovery", "Never with the correlation ID propagated to the service within the SLA agreed upon with the merchant", "Only in external CMSs for analytical use cases in data migration scenarios", "Only on mobile, using the current commit pipeline and following the pattern defined in SFRA"], "explanation": "Generating the sitemap from the actual inventory reduces 404 errors and incorrect canonical tags."}, "q78": {"text": "Why use search filters for canonicalization?", "options": ["To reduce inventory using SOAP web services", "For technical SEO and to avoid duplicate content", "To populate the sitemap for advanced reporting purposes", "To improve page speed for analytics use cases"], "explanation": "Without a canonical tag, filters generate nearly identical pages that fragment the rankings."}, "q79": {"text": "Which piece of data should not be included in cached shared HTML?", "options": ["Product Name", "Category Description", "Customer ID and My Cart", "Product image"], "explanation": "The cached page must be secure for all users who share the same password."}, "q80": {"text": "What can ruin the cache hit ratio?", "options": ["Public Content for Analytical Use Cases", "A TTL Suitable for Analytical Use Cases", "Versioned assets for analytical use cases", "A key hashed using a unique cookie"], "explanation": "Varying by unique data creates one entry per user and prevents effective reuse."}, "q81": {"text": "What else should be measured besides the overall hit ratio?", "options": ["Hit ratio by route", "Number of comments", "Team size", "Number of roles"], "explanation": "The global average may mask a critical PDP or PLP with degraded cache performance."}, "q82": {"text": "Which optimization typically has the greatest impact?", "options": ["Run more code during the page rendering phase", "Prevent code execution using a secure cache", "Add services to the PDP for analytical use cases", "Save responses in the session"], "explanation": "A response served from the correct layer saves the application work and reduces latency."}, "q83": {"text": "Which layer controls remote includes?", "options": ["ELB in the page rendering phase", "Sitemap for Analytical Use Cases", "Page Cache and the include file itself", "Service Framework"], "explanation": "The remote include executes an internal sub-request; its cache is defined at the include level."}, "q84": {"text": "What does a stale-while-revalidate pattern achieve?", "options": ["Cache forever using the current commit pipeline", "Bypass the cache based on the site's regional settings", "Always invalidate with the support of the operations team", "Serve the old cache while it regenerates in the background"], "explanation": "Balances refresh rate and latency; reduces occasional slow responses."}, "q85": {"text": "How does Salesforce invalidate the page cache?", "options": ["TTL + URL-based invalidation using a surrogate key", "Reloading the class through the presentation layer", "Restarting the server for analytical use cases", "Automatically with each import"], "explanation": "Surrogate keys allow you to invalidate logical groups without flushing the entire cache."}, "q86": {"text": "What makes it easier to track a request between SFCC and providers?", "options": ["CVV", "Correlation ID", "Customer password", "Duplicate cartridge"], "explanation": "A correlation identifier allows you to link logs and metrics end-to-end."}, "q87": {"text": "Why isn't it a good idea to memorize just one payment amount?", "options": ["Because there are no quotas for analytical use cases", "Because they only apply CSS to analytical use cases", "Because they depend on the resource and can evolve", "Because the browser decides them"], "explanation": "You must verify the current quota and set up monitoring and alerts before the deadline."}, "q88": {"text": "What should not appear in logs?", "options": ["Service Life", "Error Category", "Correlation ID", "Tokens and Unmasked PII"], "explanation": "Logs should provide operational context without revealing secrets or personal data."}, "q89": {"text": "Which alert is most useful?", "options": ["One focused on client symptoms and SLOs", "Any isolated warning", "A threshold-free approach using scheduled jobs", "CPU only, once a month"], "explanation": "Actionable alerts link latency, errors, and critical flows to real-world impacts."}, "q90": {"text": "What does a well-designed log category contain?", "options": ["Text only", "Name, level, and sink", "Warnings only", "Errors Only"], "explanation": "Categories separated by domain allow for granularity and volume control."}, "q91": {"text": "Why measure quota headroom?", "options": ["Just out of curiosity, within the standard checkout process", "For SEO during synchronization with the OMS", "To set capacity limits and alerts before reaching the limit", "For compliance with the current deployment model"], "explanation": "Designing with a margin helps prevent issues when a partner experiences traffic spikes."}, "q92": {"text": "What typically triggers a quota incident?", "options": ["Admin login during the page rendering phase for analytical use cases", "Logo change via the overnight cataloging service", "Reloading CSS according to the vendor's upgrade guide", "A massive export, an unbounded job, or a loop in a hot path"], "explanation": "Quota incidents are usually caused by spikes in usage: unmetered exports, jobs that iterate through millions of records, or loops on a hot path."}, "q93": {"text": "An authenticated user requests an address by ID. What check is missing?", "options": ["The owner of the resource", "The color of the button", "The catalog index", "The Master Price Book"], "explanation": "Without resource-level authorization, there is a risk of IDOR even if there is a valid session."}, "q94": {"text": "What does contextual output encoding prevent?", "options": ["Overselling", "XSS", "Deadlocks", "Timeouts"], "explanation": "The output must be escaped depending on whether it is inserted into HTML, an attribute, a URL, or JavaScript."}, "q95": {"text": "Which privacy principle reduces risk through design?", "options": ["Save everything indefinitely", "Copy production to any sandbox", "Minimization and Defined Retention", "Log complete payloads"], "explanation": "Retaining only necessary data for a specified period reduces exposure and obligations."}, "q96": {"text": "How should a webhook be validated?", "options": ["By its User-Agent using SOAP web services", "With a shopper cookie for analytical use cases", "Only for the body in data migration scenarios", "With a signature, timestamp, and anti-replay protection"], "explanation": "The authenticity and freshness of the message prevent forgery and the re-requesting of valid events."}, "q97": {"text": "Why doesn't CSRF replace authentication?", "options": ["Because CSRF only prevents actions from an unauthorized context; it does not verify identity", "Because it has been verified to be incompatible in the staging environment for analytical use cases", "Because it is slow when it comes to advanced reporting using scheduled jobs", "Because it doesn't work on mobile devices when following the pattern defined in SFRA"], "explanation": "Layered defense: Each control addresses a different threat."}, "q98": {"text": "Which output encoding contexts are used in ISML?", "options": ["HTML Only for Analytical Use Cases", "HTML, attribute, URL, JavaScript", "URLs via external webhooks only", "CSS Only for Analytical Use Cases"], "explanation": "Each context has its own specific escape rules; the same value may require different handling."}, "q99": {"text": "What is a DSAR, and how does it affect SFCC?", "options": ["An SQL query", "A client request for access or deletion that must be coordinated with downstream systems", "A type of promotion", "An export job"], "explanation": "Compliance with DSAR requires data traceability in SFCC and integrations."}, "q100": {"text": "What does SLAS stand for?", "options": ["Salesforce Local Authentication Server", "Secure Login Administration Site", "Storefront Link Access System", "Shopper Login and API Access Service"], "explanation": "SLAS is the Shopper Login and API Access Service for composable shopper access and authentication."}, "q101": {"text": "Which flow corresponds to a public client?", "options": ["Authorization Code with PKCE", "Client Credentials with a Secret Stored in the Browser", "Password in localStorage", "Shared Basic Authentication"], "explanation": "A public client cannot keep secrets; PKCE protects the exchange of code."}, "q102": {"text": "Are OCAPI and SCAPI equivalent?", "options": ["Yes, during the initialization of the controller using SOAP web services", "No; they are families with different authentication, extensibility, and evolution capabilities.", "They differ only in name for advanced reporting purposes", "SCAPI is an ISML template that follows the pattern defined in SFRA"], "explanation": "They should be evaluated based on use case and architecture, not treated as aliases."}, "q103": {"text": "In a headless setup, where should a client secret be stored?", "options": ["In the browser's JavaScript", "In the query string", "On a server or BFF", "In a public cookie"], "explanation": "Only a confidential server component can safeguard client secrets."}, "q104": {"text": "What do OCAPI Hooks cover?", "options": ["Caching pages in preview and staging modes for analytical use cases", "Replacing Templates Using a Distributed Cache", "Compile code via external webhooks validated against the API contract", "Customizing Shop API and Data API Responses at Supported Endpoints"], "explanation": "Hooks add logic at specific points, but they also introduce coupling with the platform."}, "q105": {"text": "What is the difference between SLAS private and public clients?", "options": ["The private key is stored securely on the server; the public key uses PKCE without a secret", "None of them offer the observability that logging provides for analytical use cases", "The public is for admins with automatic retries configured", "The private service is mobile through the use of SOAP web services"], "explanation": "Choosing the right model affects the security and architecture of the BFF."}, "q106": {"text": "What does the shopper context contain?", "options": ["Only siteId during the cart consolidation phase", "shopper's siteId, locale, currency, and relevant data", "Solo currency validated against the API contract", "Nothing is normalized in preview and staging mode"], "explanation": "The shopper context is passed along in most SCAPI calls and applies selection rules."}, "q107": {"text": "What provides the best protection for an extended route during an upgrade?", "options": ["Delete logs", "An undocumented replacement", "Regression Tests", "Never update"], "explanation": "The tests detect changes to the contract and behavior in SFRA or third-party cartridges."}, "q108": {"text": "What test validates the contract with an OMS?", "options": ["A sitemap", "CSS Snapshot Only", "A Typography Test", "Contract/integration test"], "explanation": "Contract tests detect incompatibilities in payloads, states, and errors."}, "q109": {"text": "What reduces the cost of an SFRA update?", "options": ["Small, well-documented overrides", "Copy Entire Controllers", "Modify the database for analytical use cases", "A monolithic cartridge"], "explanation": "The smaller and more explicit the custom delta is, the easier it is to compare and adopt base changes."}, "q110": {"text": "What should a comprehensive quality strategy include?", "options": ["Unit tests only with authorization from the platform team", "Unit, integration, API, E2E, performance, and risk-based security", "Manual testing only in data migration scenarios", "Just lint with the cartridge's default configuration"], "explanation": "Each level detects different types of failures and must prioritize critical business flows."}, "q111": {"text": "How do you mock dw/* in unit tests?", "options": ["Connects to production", "This cannot be verified in the staging environment.", "Using specific stubs that emulate the API", "Sandbox-only for analytical use cases"], "explanation": "The dw/* mocks isolate the code under test and allow it to be executed in standard CI."}, "q112": {"text": "What do contract tests reveal?", "options": ["CSS Styles Using SOAP Web Services", "XSS Detection Using a Distributed Cache", "Site Speed Using Scheduled Jobs", "Payload Compatibility and Error Handling"], "explanation": "Contract tests protect the integration from uncoordinated upstream changes."}, "q113": {"text": "Which upgrade strategy is the safest?", "options": ["Rollout by cartridge, by route, or by feature flag with smoke tests", "Big Bang Using a Distributed Cache for Analytical Use Cases", "Only in the sandbox via external webhooks for analytical use cases", "Skip releases during controller initialization"], "explanation": "Splitting the change reduces the blast radius and facilitates granular rollback."}, "q114": {"text": "The ERP must be queried at each PDP. What is the best approach?", "options": ["Synchronous call without a timeout, monitored by the standard dashboard", "Incremental replication, eventually consistent data, and critical revalidation", "Save stock in a cookie with automatic retries configured", "Disable the global cache using SOAP web services"], "explanation": "The architecture decouples navigation from the ERP and reserves strict validation for critical points."}, "q115": {"text": "How can I reliably export orders to the OMS?", "options": ["No external key in the cart consolidation phase", "Manually aligned only with current best practices", "Incremental, idempotent, confirmed, and reconcilable", "Mark them as exported before sending"], "explanation": "Watermarking, idempotence, acknowledgment, retry, and reconciliation prevent data loss and duplicates."}, "q116": {"text": "How can I customize it without clearing the cache?", "options": ["Update all PDPs by customer ID during synchronization with the OMS", "Optimize the code with a focus on code maintainability", "Disable CDN based on the current deployment model", "Isolate dynamic fragments and maintain the shared shell"], "explanation": "The shared content remains cacheable, and only the personalized portion is rendered dynamically."}, "q117": {"text": "What is the secure way to deploy a new required attribute?", "options": ["Metadata, tolerant code, data, index, and gradual activation", "Code that fails if missing, before metadata", "Delete the catalog in coordination with the operations team", "Change production directly during the cart consolidation phase"], "explanation": "Organizing dependencies and using temporary compatibility enables safe rollouts and rollbacks."}, "q118": {"text": "How should we approach an international multi-site operation?", "options": ["Replicate everything using the site's regional settings through the presentation layer", "Decide what to share (master) and what to localize (storefront, price, language)", "A monolithic site within the standard checkout flow for analytical use cases", "Manually Replicate the Configuration During Synchronization with the OMS"], "explanation": "Defining the sharing model is the most important architectural decision."}, "q119": {"text": "Why should you avoid a \"big bang\" cutover in an SFRA→PWA Kit hybrid?", "options": ["It doesn't look elegant through the presentation layer", "It is illegal as it violates the external API contract", "It involves migrating everything at once, which carries high risk and entails costly recovery.", "It is not possible through the night cataloging service"], "explanation": "Phased rollouts using eCDN and session bridging reduce risk and enable early feedback."}, "q120": {"text": "What attribute justifies a new search index?", "options": ["Any CSS changes for analytics use cases", "Hostname change verified in the staging environment", "Logo Change for Advanced Reporting Purposes", "An attribute that becomes filterable or sortable"], "explanation": "Only attributes displayed in the search UI justify maintaining an up-to-date index."}, "q121": {"text": "What best describes a customer group?", "options": ["A group of shoppers who are all eligible for the same prices, promotions, and coupons", "An aesthetic label in the context of the international storefront for analytical use cases", "An import bucket using scheduled jobs via external webhooks", "A folder containing files authorized by the platform team"], "explanation": "Customer groups govern pricing, discounts, and many business rules."}, "q122": {"text": "What is a customer list used for?", "options": ["Save cart during synchronization with the OMS", "Targeting of coupons, content, and campaigns", "Index products via external webhooks", "Caching Responses for Analytical Use Cases"], "explanation": "The lists group shoppers together for targeted marketing campaigns and promotions."}, "q123": {"text": "What roles are typically found in a B2B account hierarchy?", "options": ["Visitor during synchronization with the OMS", "Root access only for analytical use cases", "Approver, buyer, admin, and custom roles", "Email only via SOAP web services"], "explanation": "Each role defines permissions and approval workflows that are consistent with the hierarchy."}, "q124": {"text": "Which piece of data should NOT be stored in `session.custom`?", "options": ["The Temporal Language for Analytical Use Cases", "The Anonymous ID for Analytical Use Cases", "The Status of the Wizard for Analytical Use Cases", "PII included in the consolidated profile"], "explanation": "session.custom is short-lived and small; PII must be consolidated in CustomerProfile."}, "q125": {"text": "Why is it tricky to move a shopper to another customer group?", "options": ["It affects your eligibility for pricing, promotions, and coupons; it must be reviewed", "It does not prioritize code maintainability", "It affects SEO depending on the current deployment model during the page rendering phase", "Change the URL using the standard dashboard monitoring"], "explanation": "A change in group may affect price and coupon expectations."}, "q126": {"text": "What workflow should be in place when switching from guest to registered?", "options": ["None through the night cataloging service", "Idempotent basketball transfer and line item reconciliation", "Overwrite the basket in coordination with the operations team", "Create an order during the cart consolidation phase"], "explanation": "The merge prevents shoppers from losing their selections and reduces support tickets."}, "q127": {"text": "Which lifecycle event triggers the consolidation of a guest into a Customer?", "options": ["Log out of the session", "Deleting Cookies", "Sign up with email or social media login", "Change Language"], "explanation": "Logging in with valid credentials triggers the creation of the Customer record and the consolidation of shopping carts and guest shopper data."}, "q128": {"text": "What determines the priority of a promotion?", "options": ["Aesthetics through the presentation layer alone", "The duration validated against the external API contract", "Language in the page rendering phase for analytical use cases", "The evaluation order compared to other promotions for the same basket"], "explanation": "A clearly defined priority prevents unwanted discount combinations."}, "q129": {"text": "What happens if two promotions are mutually exclusive?", "options": ["The priority one is applied, and the other is discarded for combos involving the same item", "The \"basket\" for analytical use cases in data migration scenarios has been canceled", "They are duplicated using the current commit pipeline, following the pattern defined in SFRA", "None of these apply to the site's regional configuration for analytical use cases"], "explanation": "Exclusion protects margins and must be explicitly defined in the business logic."}, "q130": {"text": "What happens when you add a coupon to your cart?", "options": ["The total does not change when using SOAP web services", "The engine recalculates and applies (or does not apply) based on rules and eligibility", "The coupon is queued using scheduled jobs", "An order is created with the platform team's authorization"], "explanation": "Immediate recalculation prevents phantom discounts and maintains a consistent user experience."}, "q131": {"text": "What are the risks of an unmonitored single-use coupon?", "options": ["Swim in preview and staging mode with monitoring via the standard dashboard", "Reducing Latency Through the Use of Distributed Caching for Analytical Use Cases", "It should be redeemed more than once if two requests are received almost simultaneously (race condition)", "Site crash during controller initialization for analytical use cases"], "explanation": "Concurrency control (lock, atomic counter) is required for sensitive coupons."}, "q132": {"text": "Which test is essential for validating promotional combinations?", "options": ["Snapshot showing standard dashboard monitoring for analytical use cases", "A guide to the observability provided by logs for analytical use cases", "Only A/B testing with automatic retries configured during the page rendering phase", "A test that cycles through all active combinations with rounding by currency"], "explanation": "Combinatorics and rounding reveal costly bugs in production."}, "q133": {"text": "Which attribute exports reliable metrics for promotions?", "options": ["Exchanges, incremental revenue, churn, and uplift by segment", "Nothing in line with current best practices", "Field validated against the API contract", "Name only in preview and staging mode"], "explanation": "Structured metrics help protect margins and enable informed decision-making."}, "q134": {"text": "Which attribute of a promotion determines whether it can be combined with others at the same level?", "options": ["Only the internal name during synchronization with the OMS", "The exclusivity flag or the exclusion setting", "The duration of the campaign based on the current deployment model", "The site language with standard dashboard monitoring"], "explanation": "The exclusivity settings and exclusion sets determine which promotions can coexist or are mutually exclusive."}, "q135": {"text": "What is the purpose of a synonym in a search?", "options": ["To place an order through the overnight cataloging service", "To perform a cache check following the vendor's upgrade guide for analytical use cases", "To expand the query with equivalent terms and improve coverage", "For pagination during the cart consolidation phase for analytical use cases"], "explanation": "Synonyms prevent zero results when the shopper uses a term different from the one in the catalog."}, "q136": {"text": "What does a boost rule do?", "options": ["Sort by price based on the site's regional settings", "Change the language with the help of the operations team", "Exclude results from the standard checkout flow", "Promote certain products in specific search queries"], "explanation": "Boost is a per-query merchandising tool, not a global change."}, "q137": {"text": "What is a search redirect?", "options": ["Display an alternative URL when the query has no relevant results", "A 404 page validated against the external API contract", "An HTTP redirect during the page rendering phase for analytics use cases", "A promotion using the overnight cataloging service"], "explanation": "Redirects turn unsuccessful searches into useful landing pages."}, "q138": {"text": "Which pagination strategy is most SEO-friendly?", "options": ["Infinite scrolling without pagination for analytical use cases", "Pagination with unique URLs and canonical URLs where appropriate", "JavaScript only via the current commit pipeline", "Do not index using the site's regional settings"], "explanation": "Real, unique URLs enable crawling, ranking, and consistent canonicalization; pure infinite scrolling does not provide pagination signals to search engines."}, "q139": {"text": "When is server-side autocomplete a good idea?", "options": ["Always in accordance with the SLA agreed upon with the merchant", "Never in data migration scenarios", "When the data source is large or requires authorization", "When a 5G network is available through the presentation layer"], "explanation": "Delegating to the server reduces client-side costs and enables centralized business rules."}, "q140": {"text": "Which attribute should not be refinable?", "options": ["Color for Analytical Use Cases", "Sizing for analytical use cases", "Product Type", "Internal Audit Attribute"], "explanation": "Filtering by internal fields exposes information and distorts the UI."}, "q141": {"text": "What are the consequences of marking an attribute as \"searchable\" without reindexing the catalog?", "options": ["It doesn't appear in the results until it's reindexed", "Increase search latency for analytical use cases", "The sitemap fails with automatic retries configured", "Override the cache by using SOAP web services"], "explanation": "The search index only reflects the attributes as of the time of the last rebuild; without reindexing, the attribute does not affect the results."}, "q142": {"text": "What is an RMA?", "options": ["A promotion during the cart's consolidation phase", "A return authorization with a reason and policy", "A job validated against the API contract", "A cookie in preview and staging mode"], "explanation": "The RMA is the cornerstone of any controlled returns process."}, "q143": {"text": "What key information must a refund include?", "options": ["It only mounts during synchronization with the OMS", "Payment token with a focus on code maintainability", "Idempotent reference, method, and amount aligned with entry", "Comment on the standard dashboard monitoring"], "explanation": "Without idempotence, a refund can be processed twice and leave the system in an inconsistent state."}, "q144": {"text": "What should be done with the inventory for an approved RMA?", "options": ["Block all shoppers for analytical use cases", "Nothing, following the vendor's upgrade guide", "Remove products in coordination with the operations team", "Release the ATS or mark it as damaged and notify the OMS"], "explanation": "The policy determines whether the product is returned to stock, discarded, or inspected."}, "q145": {"text": "Is canceling before shipment no big deal?", "options": ["Requires canceling the reservation, issuing a refund, and notifying the integration partners", "Yes, with support from the operations team for analytical use cases", "\"Cancel\" button only within the standard checkout flow", "Not allowed during synchronization with the OMS"], "explanation": "Ensuring consistency prevents double billing and frees up logistics capacity."}, "q146": {"text": "Why avoid a complex edit after `placeOrder`?", "options": ["For aesthetic reasons, through the presentation layer within the SLA agreed upon with the merchant", "Because reconstructing a valid order and forwarding it to OMS is safer than modifying it", "It is not technically permitted during the page rendering phase for analytical use cases", "Via SEO using the nightly cataloging service through the presentation layer"], "explanation": "Canceling + creating a new order reduces errors and keeps the audit trail clean."}, "q147": {"text": "What audit log should be maintained for a refund?", "options": ["I only mount it with the correlation ID propagated to the service", "Client-only for analytical use cases", "Operator, reason, correlation ID, amount, and method", "Date based solely on the site's regional settings"], "explanation": "An audit makes it possible to understand disputes and verify decisions."}, "q148": {"text": "What information should NOT be included in an RMA response to the shopper?", "options": ["Current Status of the RMA for Analytical Use Cases", "General rationale and policy implemented", "Next Steps in the Process", "Internal identifiers of the OMS or the agent"], "explanation": "Disclosing internal OMS or agent IDs allows for correlation between incidents and reveals the architecture; they must remain in the log."}, "q149": {"text": "What is the Retail React App?", "options": ["An SSR/CSR template from PWA Kit optimized for e-commerce", "A CMS for advanced reporting", "A Business Manager add-on that follows the pattern defined in SFRA", "A checkout library within the SLA agreed upon with the merchant"], "explanation": "The Retail React App is the official template that provides pages, components, and tooling."}, "q150": {"text": "What does the request processor do in PWA Kit?", "options": ["Server-side rendering with standard dashboard monitoring", "Modify the query string at the edge to improve the cache hit ratio", "Build bundles with automatic retries configured", "Connect to the database using SOAP web services"], "explanation": "Filtering out irrelevant parameters (utm, gclid) before the cache lookup increases the hit ratio."}, "q151": {"text": "What is the default TTL for the page cache in Managed Runtime?", "options": ["60 s", "One hour", "600 s", "24 hours"], "explanation": "The default can be set per page in `getProps` or centrally in `app/ssr.js`."}, "q152": {"text": "What does commerce-sdk-react offer?", "options": ["A database during synchronization with the OMS", "An ERP system focused on code maintainability", "An SFRA license based on the current deployment model", "Hooks for SLAS and SCAPI with TanStack Query Caching"], "explanation": "This is the recommended layer for communicating with SCAPI and SLAS in PWA Kit."}, "q153": {"text": "What is template extensibility?", "options": ["Override in overrides/app to reduce footprint and upgrade debt", "Delete the database by following the vendor's upgrade guide", "Hardcode in coordination with the operations team", "Compile offline during the cart consolidation phase"], "explanation": "Customizing via overrides allows for clean upgrades of the base template."}, "q154": {"text": "Which browsers does PWA Kit officially support?", "options": ["Anyone with the site's regional settings", "The two most recent major versions of modern, standard browsers", "Chrome only within the standard checkout flow", "Safari Only During Synchronization with the OMS"], "explanation": "The support is documented and should be aligned with actual analytics."}, "q155": {"text": "Which architectural decision reduces TCO?", "options": ["Manual forks through the presentation layer", "Update not validated against the external API contract", "Adopt template extensibility and update frequently", "Rewrite each year using the nightly cataloging service"], "explanation": "Small, regular updates reduce the total cost compared to major upgrades."}, "q156": {"text": "Which MRT technique allows cached pages to be served when part of the content depends on the user?", "options": ["Full cache invalidation with the correlation ID propagated to the service within the SLA agreed upon with the merchant", "Disable the CDN for analytics use cases in data migration scenarios for analytics use cases", "Cache the user's cookie using the current commit pipeline, following the pattern defined in SFRA", "Conditional rendering: server-side without personal data + client-side hydration for dynamic content"], "explanation": "The server-side delivers the cacheable shell, and client-side hydration adds the custom fragments without affecting the cache hit ratio."}, "q157": {"text": "Which pattern is the safest for migrating a legacy system?", "options": ["Strangler pattern with coexistence and session bridging", "Eliminating Legacy Systems in Data Migration Scenarios", "Document only using the cartridge's default settings", "Big Bang Through the Presentation Layer"], "explanation": "Strangler introduces route-based SFRA/composable and minimizes big bangs."}, "q158": {"text": "What common mistake ruins a migration?", "options": ["Test with limited verification in the staging environment", "Copy SiteGenesis to SFRA instead of rewriting it", "Write tests following the pattern defined in SFRA", "Versions with the correlation ID propagated to the service"], "explanation": "Copying SiteGenesis verbatim into SFRA preserves the legacy anti-patterns (transactional scripts, spaghetti ISML, unnecessary hooks) and doubles the technical debt."}, "q159": {"text": "What should be done with the legacy OCAPI Hooks?", "options": ["They are excluded in the context of the international storefront", "They are renamed using scheduled jobs", "They are rewritten as SFRA extensions or justified in Composable.", "They are not covered under the SLA agreed upon with the merchant"], "explanation": "Each hook must be evaluated individually: some remain useful, others have become obsolete due to the migration to SCAPI, and still others can be rewritten as SFRA extensions or logic in the BFF."}, "q160": {"text": "Which decision carries the most weight at the start of the project?", "options": ["Choosing a framework during the cart consolidation phase", "Choose a color that aligns with current best practices", "Choose hosting that complies with the API agreement", "Take inventory of cartridges, customizations, and data"], "explanation": "Without an inventory, the plan becomes nothing more than a promise, and the timeline ends up being unrealistic."}, "q161": {"text": "How does QA compare across legacy systems?", "options": ["Regression suite against SiteGenesis and performance comparison", "A unit test focused on code maintainability", "I only use Smoke based on the current deployment model for analytical use cases", "Keep an eye on the standard dashboard metrics"], "explanation": "Without a reproducible regression suite against the legacy version, it is not possible to verify functional parity or detect regressions introduced by the migration."}, "q162": {"text": "Why is communication important to merchants?", "options": ["It doesn't matter which night cataloging service is used", "To align expectations regarding cuts, content, and campaigns", "Only at the start, in coordination with the operations team", "Only at the end, during the cart's consolidation phase"], "explanation": "A merchant who is well-informed about outages, content, and campaigns reduces support tickets, prevents crises, and maintains trust even when technical incidents occur."}, "q163": {"text": "What are the risks of a \"big bang\" cut-over on a production storefront?", "options": ["Reducing Operating Costs Through Regional Site Configuration", "Automated SEO optimization with support from the operations team", "Loss of business if regressions occur without the possibility of a quick rollback", "Reduction of Technical Debt During Synchronization with the OMS"], "explanation": "Without a quick rollback, a critical regression directly impacts revenue, and recovery is costly; phased rollouts reduce this risk."}, "q164": {"text": "What does session bridging enable?", "options": ["Merging two sites via the presentation layer, tested in the staging environment", "Merge catalogs validated against the external API contract", "Merge orders during the page rendering phase using the presentation layer", "Sharing Identity Between SFRA Storefronts and PWA Kit (or SiteGenesis with POC)"], "explanation": "The shopper retains their session while navigating between architectures."}, "q165": {"text": "Which cookie corresponds to the SLAS refresh token for guests?", "options": ["cc-nx-g", "cc-at", "dwsid", "PHPSESSID"], "explanation": "cc-nx-g stores the guest's refresh token; cc-nx is for registered shoppers."}, "q166": {"text": "What does the SLAS Plugin cartridge do today?", "options": ["It is obsolete under the SLA agreed upon with the verified merchant in the staging environment.", "It acts as an SFRA-SLAS bridge; in newer versions, it is replaced by Hybrid Auth", "Compile Java using the cartridge's default configuration", "Performs SEO through the presentation layer within the SLA agreed upon with the merchant"], "explanation": "The SLAS plugin enabled hybrid mode; Hybrid Auth is the supported solution starting with version 25.3."}, "q167": {"text": "What rule does eCDN use to route traffic to PWA Kit?", "options": ["Browser hash verified in the staging environment", "Session cookie for advanced reporting purposes", "Cloudflare expression by host, path, URI, or cookie", "User token within the SLA agreed upon with the merchant"], "explanation": "eCDN relies on Rule Expressions; it is best to keep rules simple and testable."}, "q168": {"text": "How many rules does eCDN support per instance in proxy zones?", "options": ["10", "No limit", "1,000", "100"], "explanation": "100 rules per instance in proxy zones; 100 shared rules in legacy zones."}, "q169": {"text": "What attribute do shared cookies use to maintain the shopping cart?", "options": ["dwsid", "PHPSESSID", "cc-at_{siteId}", "session.custom"], "explanation": "cc-at_{siteId} passes the access token across the architectural boundary."}, "q170": {"text": "Which cookie is updated when the shopper switches between SFRA and the authenticated PWA Kit?", "options": ["cc-nx-g during synchronization with the OMS", "dwsid after the call to OCAPI's /sessions", "PHPSESSID based on the current deployment model", "JSESSIONID during the cart consolidation phase"], "explanation": "PWA Kit notifies SFRA via an OCAPI POST request to /sessions; the response includes a new dwsid that links the B2C Commerce session to SLAS."}, "q171": {"text": "Which SLO is the top priority for a storefront?", "options": ["Aesthetics through the nighttime cataloging service", "Number of features according to the vendor's upgrade guide", "Checkout Conversion Rate and P95 Latency by Critical Path", "Team size during the cart consolidation phase"], "explanation": "SLOs must reflect the actual impact on shoppers and the business."}, "q172": {"text": "What does a useful runbook contain?", "options": ["Only URLs with the site's regional settings", "Just a description with support from the operations team", "Contact only within the standard checkout process", "Symptoms, metrics, logs, pre-approved mitigation, and escalation"], "explanation": "An actionable runbook describes detectable symptoms, key metrics, log queries, pre-approved mitigation steps (including a kill switch), and escalation contacts; it reduces MTTR and prevents heroics."}, "q173": {"text": "Which alerts are actionable?", "options": ["P95 latency + 5xx rate per critical path", "CPU once a month for analytical use cases", "Every warning during the page rendering phase", "Random log via the presentation layer"], "explanation": "A good alert includes a threshold, a symptom, and a path to the runbook."}, "q174": {"text": "Which postmortem is correct?", "options": ["Find the culprit using the correlation ID propagated to the service", "Document the timeline, causes, and action items without assigning blame", "It is hidden by the current commit pipeline", "Share only with the manager based on the site's regional settings"], "explanation": "A blame-free culture allows us to learn from the incident and prevent it from happening again."}, "q175": {"text": "What should you do when MTTR is increasing?", "options": ["Rotate on-call duties within the SLA agreed upon with the merchant", "Increase Severity in Data Migration Scenarios", "Identify gaps in runbooks, alerts, and observability", "Reducing on-call duty through the presentation layer"], "explanation": "A rising MTTR typically indicates incomplete runbooks, poorly designed alerts, or a lack of observability; rotating on-call duty merely shifts the problem around without resolving it."}, "q176": {"text": "What should you do if a rollback doesn't take effect?", "options": ["Switching verified platforms in the staging environment", "Force for advanced reporting purposes via external webhooks", "Delete data according to the pattern defined in SFRA", "Identify data inconsistencies and prepare a fix-forward"], "explanation": "Forcing a rollback when the data has changed can break integrations."}, "q177": {"text": "What is a budget error in SRE?", "options": ["Maximum tolerable error in a window (1 - SLO)", "Financial Budget for Incidents via External Webhooks", "Runbook template with authorization from the platform team", "Cost of on-call rotation within the SLA agreed upon with the merchant"], "explanation": "The budget error is calculated as 1 minus the SLO (e.g., a 0.1% error margin if the SLO is 99.9%); it limits how much risk can be taken before releases are put on hold."}, "q178": {"text": "What is the difference between a release flag and an experiment flag?", "options": ["Swimming using distributed caching for analytical use cases", "The release flag triggers the rollout; the experiment flag measures the impact", "Only the name during controller initialization", "The panel color verified in the staging environment"], "explanation": "A release flag answers the question \"Is it ready for everyone?\" and an experiment flag answers \"Which variant works best?\"; mixing them invalidates metrics and the rollout."}, "q179": {"text": "When Should You Say NO to an A/B Test?", "options": ["Never with the observability provided by logs, with a focus on code maintainability", "Always with automatic retries configured and validated against the API contract", "When the sample doesn't arrive, the metric isn't clear, or the change is cosmetic", "Mobile only, within the context of the international storefront, for analytical use cases"], "explanation": "A poorly designed test is just noise and can waste precious time."}, "q180": {"text": "What are the SEO risks of an A/B test?", "options": ["None via the nightly cataloging service for analytical use cases", "Only robots following the vendor's upgrade guide for analytical use cases", "Canonical only, in coordination with the operations team", "The variants differ in HTML, and search engines detect inconsistencies"], "explanation": "Maintaining canonical and metadata constants reduces risk."}, "q181": {"text": "What properties should a feature flag have?", "options": ["Default off, simple kill switch, and cleanup after the rollout", "Complexity with support from the operations team", "Being asynchronous within the standard checkout flow", "Change with each commit during synchronization with the OMS"], "explanation": "A well-designed flag is an explicit, time-limited toggle."}, "q182": {"text": "What is a commonly used tool for feature flags in SFCC?", "options": ["Customization only through the presentation layer for analytical use cases", "Custom Preferences, LaunchDarkly, Optimizely, or another tool as specified in the contract", "Business Manager only during the page rendering phase", "None through the night cataloging service"], "explanation": "The choice of tool depends on budget and maturity."}, "q183": {"text": "What common mistake ruins an experiment?", "options": ["Define a verified metric in the staging environment", "Establishing a baseline for analytical use cases", "Peeking and stopping the test at the first sign,", "Post-test cleaning for analytical use cases"], "explanation": "Peeking undermines significance and leads to noisy decisions."}, "q184": {"text": "What problem does dividing traffic by cookie rather than by shopper ID cause?", "options": ["Higher latency within the SLA agreed upon with the merchant for analytical use cases", "Break the sitemap in data migration scenarios for advanced reporting purposes", "Reduces the cache hit with the cartridge's default configuration", "Sessions with multiple cookies disrupt the assignment and skew the sample"], "explanation": "Cookie-based segmentation can assign the same shopper to different variants across sessions or devices, skewing metrics and experiences."}, "q185": {"text": "What does a load test measure?", "options": ["Latency, error rate, and throughput under expected load", "Accessibility for advanced reporting purposes only", "SEO only, following the pattern defined in SFRA", "Styles with the correlation ID propagated to the service"], "explanation": "A load test verifies that the system can handle the expected traffic."}, "q186": {"text": "Which test monitors the load hours to detect leaks?", "options": ["Stress", "Soak test", "Spike", "Unit"], "explanation": "The soak test reveals memory leaks and gradual degradation."}, "q187": {"text": "Which Core Web Vitals metrics matter to the PDP?", "options": ["TTFB Only", "JavaScript Only", "LCP, INP, and CLS", "CSS Only"], "explanation": "These three metrics summarize the actual user experience."}, "q188": {"text": "What decision should you make when a performance budget is exceeded?", "options": ["Ignore the observability provided by the log for analytical use cases", "Upload the budget with automatic retries configured", "Increase the price using SOAP web services", "Reduce dependencies, split bundles, or offload work at runtime"], "explanation": "The budget is a design decision that is reviewed in every PR."}, "q189": {"text": "What kind of traffic does a spike test simulate?", "options": ["Sudden spikes like viral campaigns", "Only the admin during the page rendering phase", "Login only for analytical use cases", "Flat traffic for analytical use cases"], "explanation": "The spike test verifies resilience in the face of unforeseen events."}, "q190": {"text": "What should you keep in mind when running a load test in SFCC?", "options": ["That it slows down production based on the site's regional configuration", "Quotas should be shared, and results should not be valid in the sandbox", "Only perform this within the standard checkout flow for analytical use cases", "It does not matter during synchronization with the OMS for analytical use cases"], "explanation": "Sharing the environment with real data can lead to distortions; it is best to isolate it."}, "q191": {"text": "What is the difference between a load test and a stress test?", "options": ["There is no difference across the presentation layer for analytical use cases", "Just change the name that has been validated against the external API contract", "A load test validates the expected load; a stress test seeks to find the breaking point", "The stress test only measures SEO using the nightly crawling service"], "explanation": "A load test confirms that the system can handle the expected traffic; a stress test pushes it to its limits to detect performance degradation and failure modes."}};